catalog=pagehead('Products','The right products. A clearer choice.','Explore our selected medical range, compare your options and build a quote for your facility.')+f'''<div class="catalog-layout section"><aside class="filter-panel"><div class="filter-title"><h2>Refine your selection</h2><button class="text-button" id="reset-filters">Reset</button></div><fieldset><legend>Product family</legend><label class="filter-option"><input type="radio" name="category" value="all" checked><span>All products</span><small>{len(products)}</small></label>{filters}</fieldset><label class="field-label" for="department-filter">Clinical department</label><select id="department-filter"><option value="all">All departments</option>{''.join(f'<option value="{d["id"]}">{e(d["name"])}</option>' for d in data['departments'])}</select><div class="filter-help">{icon('phone')}<h3>Can’t find your item?</h3><p>Share your list and we’ll help you explore the options.</p><a href="contact.html">Talk to our team {icon('arrow')}</a></div></aside><div class="catalog-results"><div class="catalog-toolbar"><div><h2 id="catalog-title">All products</h2><p id="result-count" role="status">{len(products)} selected products</p></div><label class="sort-control">Sort by <select id="sort-products"><option value="featured">Selected order</option><option value="az">Name: A–Z</option><option value="za">Name: Z–A</option></select></label></div><div class="catalog-search">{icon('search')}<label class="sr-only" for="catalog-query">Search this catalogue</label><input id="catalog-query" type="search" placeholder="Search within our selection…"><button id="saved-filter" class="text-button" aria-pressed="false">Saved products</button></div><div id="active-filters" class="active-filters"></div><div class="product-grid" id="catalog-grid">{''.join(card(p) for p in products)}</div><div id="catalog-enquiry"></div><div class="catalog-note">Configurations, pricing and availability are confirmed with your quotation. Product photographs are indicative of the listed range.</div></div></div>'''
