shell('thankyou.html','Review your enquiry','<div class="section" id="enquiry-review"></div>')
contact=pagehead('Contact','A real conversation starts here.','Product questions, bulk requirements or a facility equipment list—we’re here to help.')+f'''<div class="section contact-layout"><div class="contact-details"><span class="eyebrow">PRODUCT ENQUIRIES</span><h2>Tell us what you’re looking for.</h2><p>Our Dr. Smith product team can help you discuss configurations, pricing and availability.</p><a href="tel:18008917466">{icon('phone')}<span><small>Call the team</small>1800 8917466</span></a><a href="mailto:info@drsmith.co.in">{icon('mail')}<span><small>Email your requirements</small>info@drsmith.co.in</span></a><p class="muted">New Delhi, India<br>For visits and experience-centre availability, please contact the team first.</p></div><form id="contact-form" class="form-card"><h2>Prepare an enquiry</h2><div class="form-row"><label>Your name<input name="name" required autocomplete="name" maxlength="100"></label><label>Organisation<input name="organisation" autocomplete="organization" maxlength="160"></label></div><label>Email address<input name="email" type="email" required autocomplete="email" maxlength="160"></label><label>What do you need?<textarea name="message" id="contact-message" required rows="6" maxlength="3000" placeholder="Product, quantity, configuration and delivery city…"></textarea></label><p class="form-note">Review your message, then choose email or WhatsApp to share it. This form does not send automatically.</p><button type="submit" class="button">Review message {icon('arrow')}</button><div id="contact-review"></div></form></div>'''
shell('contact.html','Contact & support',contact)
shell('about.html','About us',pagehead('About','A better way to equip care.','Surgical Wholesale Mart brings healthcare procurement into one clear, connected experience.')+f'''<section class="section editorial-split"><div><span class="eyebrow">OUR APPROACH</span><h2>Useful products.<br>Considered choices.<br>Human support.</h2><p>From a bedside locker to an operating theatre requirement, the right conversation starts with understanding the care setting.</p><p>Our catalogue brings together hospital furniture, equipment, surgical instruments, consumables and ward essentials from the Surgical Wholesale Mart catalogue and selected Dr. Smith products. Surgical Wholesale Mart supports wider procurement and project coordination.</p><a class="button" href="products.html">Explore the selection {icon('arrow')}</a></div><div class="editorial-image"><img src="assets/products/9065d7fe01a7.png" alt="Deluxe examination couch" width="720" height="500"></div></section><section class="section"><div class="steps-grid"><article><span>01</span><h3>Clarity in the catalogue</h3><p>Focused product selections with straightforward information and product-specific enquiries.</p></article><article><span>02</span><h3>Support for procurement</h3><p>Discuss your quantities, configuration and facility requirements before ordering.</p></article><article><span>03</span><h3>A joined-up conversation</h3><p>Build one equipment list for product and project discussions.</p></article></div></section>''')
